DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_ROULSASCENDANCY' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_1','Rou''ls Ascendancy[NEWLINE]Veteran attrition and positional warfare[NEWLINE]Domination; Science as a protected fallback[NEWLINE][NEWLINE]Build a conventional economy, then turn favourable military kills into Anima. Your advantage is preserving experienced units across a long campaign, provided the shared reserve can cover the casualties you actually take.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_2','Improve food and research normally and scout defensible fronts. The capital''s small Science bonus does not fund reckless expansion. Fight safe military engagements to establish an Anima reserve before treating reconstruction as insurance.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_3','Bring the Choir Eternal and Somatic Lattices into the plan when available. Keep veteran replacements near valid friendly cities and reserve enough Anima for losses before paying for Transmigration. Use a Matriarch to reduce an exchange''s cost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_4','Protect the veterans doing the real work. Choose whether a Modern-era Great Migration is worth exhausting the reserve, and use Buddy to support a coastal campaign rather than expecting a naval aura to solve inland logistics.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_5','- Experienced land units can return instead of being replaced by fresh recruits.[NEWLINE]- Transmigration can bring a valuable military body to a useful front.[NEWLINE]- Later infrastructure improves reserve capacity and reliability.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_6','- The peaceful opening supplies little Anima or broad economic acceleration.[NEWLINE]- Reconstruction, movement and special abilities compete for one limited pool.[NEWLINE]- Restores are capped per turn; returning units are damaged and cannot immediately act.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_7','- Focus enough targets in one turn to overwhelm the restore cap, then threaten the recovery cities.[NEWLINE]- Avoid feeding isolated units into a veteran formation; use range, terrain and a technology lead.[NEWLINE]- Exploit an empty reserve after an expensive exchange or special ability.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_8','- Spending every Anima point on movement before an enemy attack.[NEWLINE]- Treating restoration as unlimited protection for civilians or all unit domains.[NEWLINE]- Returning a damaged veteran to combat before it can safely recover.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: A controlled attrition battle lets you preserve experience while Capano must keep individual Project attackers alive; do not offer easy four-Beta finishes.[NEWLINE][NEWLINE]Indigo Champion: Trading ordinary bodies can be acceptable while losing a trained partner is permanent for Red; the advantage depends on retaining Anima and winning some kills.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated Strength II attack can cause more same-turn deaths than reconstruction can cover.[NEWLINE][NEWLINE]The Filthy Realm: It''s Time to Stop can strand a concentrated army, while city disruption makes safe recovery and replacement harder.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_DESCRIPTION','Rou''ls Ascendancy');
