INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_BACKGROUND','Build a conventional economy, then turn favourable military kills into Anima. Your advantage is preserving experienced units across a long campaign, provided the shared reserve can cover the casualties you actually take.');
