INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LEADER_TRENT_ROULS_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_STRATEGY','Build a conventional economy, then turn favourable military kills into Anima. Your advantage is preserving experienced units across a long campaign, provided the shared reserve can cover the casualties you actually take.[NEWLINE][NEWLINE]Improve food and research normally and scout defensible fronts. The capital''s small Science bonus does not fund reckless expansion. Fight safe military engagements to establish an Anima reserve before treating reconstruction as insurance.[NEWLINE][NEWLINE]Bring the Choir Eternal and Somatic Lattices into the plan when available. Keep veteran replacements near valid friendly cities and reserve enough Anima for losses before paying for Transmigration. Use a Matriarch to reduce an exchange''s cost.[NEWLINE][NEWLINE]Protect the veterans doing the real work. Choose whether a Modern-era Great Migration is worth exhausting the reserve, and use Buddy to support a coastal campaign rather than expecting a naval aura to solve inland logistics.');
