INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_TEXT_1','Rou''ls Ascendancy[NEWLINE]Veteran attrition and positional warfare[NEWLINE]Domination; Science as a protected fallback[NEWLINE][NEWLINE]Build a conventional economy, then turn favourable military kills into Anima. Your advantage is preserving experienced units across a long campaign, provided the shared reserve can cover the casualties you actually take.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_TEXT_2','Improve food and research normally and scout defensible fronts. The capital''s small Science bonus does not fund reckless expansion. Fight safe military engagements to establish an Anima reserve before treating reconstruction as insurance.[NEWLINE][NEWLINE]Bring the Choir Eternal and Somatic Lattices into the plan when available. Keep veteran replacements near valid friendly cities and reserve enough Anima for losses before paying for Transmigration. Use a Matriarch to reduce an exchange''s cost.[NEWLINE][NEWLINE]Protect the veterans doing the real work. Choose whether a Modern-era Great Migration is worth exhausting the reserve, and use Buddy to support a coastal campaign rather than expecting a naval aura to solve inland logistics.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROULSASCENDANCY_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: A controlled attrition battle lets you preserve experience while Capano must keep individual Project attackers alive; do not offer easy four-Beta finishes.[NEWLINE][NEWLINE]Indigo Champion: Trading ordinary bodies can be acceptable while losing a trained partner is permanent for Red; the advantage depends on retaining Anima and winning some kills.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated Strength II attack can cause more same-turn deaths than reconstruction can cover.[NEWLINE][NEWLINE]The Filthy Realm: It''s Time to Stop can strand a concentrated army, while city disruption makes safe recovery and replacement harder.');
